    @Test
    public void testCreatePath_ReturnsAttributeViaNewParent() throws Exception {
        // Arrange
        JXPathContext mockContext = mock(JXPathContext.class);
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockAttributePointer = mock(NodePointer.class);

        // To access the protected 'parent' field in NullPropertyPointer, 
        // we use the constructor provided.
        NullPropertyPointer nullPropertyPointer = new NullPropertyPointer(mockParent);

        // We need to mock getName() which is part of the class. 
        // Since it's a real object, we might need to spy it if it returns null.
        NullPropertyPointer spyPointer = spy(nullPropertyPointer);
        QName mockQName = new QName("testProperty");
        doReturn(mockQName).when(spyPointer).getName();

        // Mock behavior
        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createAttribute(eq(mockContext), eq(mockQName))).thenReturn(mockAttributePointer);

        // Act
        NodePointer result = spyPointer.createPath(mockContext);

        // Assert
        verify(mockParent).createPath(mockContext);
        verify(mockNewParent).createAttribute(mockContext, mockQName);
        assert(result == mockAttributePointer);
    }

